{"path": "/Users/krypto/GitHub/ollama-eko-chat-read-integrity/app/ui/app/src/utils/remarkCitationParser.ts", "file_sha256": "fda18778386aecda5aac3d49d1cb36bc9593500761dd29f1fb3e9a80011af92c", "total_lines": 119, "text": "1: import { visit } from "unist-util-visit";
2: import type { Root, RootContent } from "mdast";
3: import type { Node } from "unist";
4: 
5: interface CitationNode extends Node {
6:   type: "custom-citation";
7:   data: {
8:     hName: "ol-citation";
9:     hProperties: { cursor: string; start?: string; end?: string };
10:   };
11: }
12: 
13: declare module "mdast" {
14:   interface PhrasingContentMap {
15:     customCitation: CitationNode;
16:   }
17:   interface RootContentMap {
18:     customCitation: CitationNode;
19:   }
20: }
21: 
22: export default function remarkMyDelimiter() {
23:   return (tree: Root) => {
24:     // First pass: convert citations to nodes
25:     visit(tree, "text", (node, index, parent) => {
26:       // Example: 【1†L25-L30】
27:       // should be parsed into:
28:       // cursor: 1, start: 25, end: 30
29:       const regex = /【(\d+)†L(\d+)-L(\d+)】/g;
30:       let match;
31:       let last = 0;
32:       const pieces: RootContent[] = [];
33: 
34:       while ((match = regex.exec(node.value))) {
35:         // text before the delimiter
36:         if (match.index > last) {
37:           pieces.push({
38:             type: "text",
39:             value: node.value.slice(last, match.index),
40:           });
41:         }
42:         // the delimited content → new custom node
43:         pieces.push({
44:           type: "custom-citation" as const,
45:           data: {
46:             // tell rehype/rehype-react to render <Citation>
47:             hName: "ol-citation",
48:             hProperties: {
49:               cursor: match[1],
50:               start: match[2],
51:               end: match[3],
52:             },
53:           },
54:         });
55:         last = match.index + match[0].length;
56:       }
57: 
58:       // After handling range-style citations, handle generic ones in the remaining text
59:       // Generic style citations like [1†...] should also be parsed as citations
60:       const remaining = node.value.slice(last);
61:       const generic = /【(\d+)†[^】]*】/g;
62:       let gLast = 0;
63:       while ((match = generic.exec(remaining))) {
64:         if (match.index > gLast) {
65:           pieces.push({
66:             type: "text",
67:             value: remaining.slice(gLast, match.index),
68:           });
69:         }
70:         pieces.push({
71:           type: "custom-citation" as const,
72:           data: {
73:             hName: "ol-citation",
74:             hProperties: {
75:               cursor: match[1],
76:             },
77:           },
78:         });
79:         gLast = match.index + match[0].length;
80:       }
81: 
82:       // trailing text after generic
83:       if (gLast < remaining.length) {
84:         pieces.push({ type: "text", value: remaining.slice(gLast) });
85:       }
86: 
87:       if (pieces.length) {
88:         parent?.children?.splice(index ?? 0, 1, ...pieces);
89:         return (index ?? 0) + pieces.length;
90:       }
91:     });
92: 
93:     // Second pass: remove adjacent duplicate citations
94:     visit(tree, (node, index, parent) => {
95:       if (
96:         parent &&
97:         parent.children &&
98:         index !== null &&
99:         index !== undefined &&
100:         index > 0
101:       ) {
102:         const currentNode = node;
103:         const prevNode = parent.children[index - 1];
104: 
105:         // Check if both nodes are citations with the same cursor
106:         if (
107:           currentNode.type === "custom-citation" &&
108:           prevNode.type === "custom-citation" &&
109:           currentNode.data?.hProperties?.cursor ===
110:             prevNode.data?.hProperties?.cursor
111:         ) {
112:           // Remove the current duplicate citation
113:           parent.children.splice(index, 1);
114:           return index;
115:         }
116:       }
117:     });
118:   };
119: }"}

